//! Untimed generated call completion profile and existing-observer parity.
use std::{cell::RefCell,env,fs,fmt::Write,collections::BTreeSet};
mod ruby {include!(env!("VYBE_PROFILE_RUBY"));pub fn count()->usize{RULES.len()}}mod fortran {include!(env!("VYBE_PROFILE_FORTRAN"));pub fn count()->usize{RULES.len()}}mod washm {include!(env!("VYBE_PROFILE_WASHM"));pub fn count()->usize{RULES.len()}}
type Shape=(usize,String);type Event=(u8,usize,usize,u8);
macro_rules! shape{($name:ident,$c:ident)=>{fn $name(tree:$c::ParseTree<'_,'_>)->Shape{fn visit(p:$c::Pair<'_,'_,'_>,d:usize,s:&mut String){write!(s,"{} {:?} {d};",p.rule_name(),p.as_span()).unwrap();for c in p.into_inner(){visit(c,d+1,s)}}let mut s=String::new();for p in tree.pairs(){visit(p,0,&mut s)}(tree.consumed(),s)}}}
shape!(old_shape,before);shape!(new_shape,after);
#[derive(Debug)]struct Wrap<'a,P>{inner:&'a P,forward:bool,trace:RefCell<Vec<Event>>,outcomes:RefCell<Vec<after::program::ProfileRuleOutcome>>}
impl<'a,P> Wrap<'a,P>{fn new(inner:&'a P,forward:bool)->Self{Self{inner,forward,trace:RefCell::new(vec![]),outcomes:RefCell::new(vec![])}}}
macro_rules! flag{($name:ident,$default:expr)=>{fn $name(&self)->bool{if self.forward{self.inner.$name()}else{$default}}}}
macro_rules! observer{($c:ident,$($extra:tt)*)=>{impl<P:$c::program::Program> $c::program::Program for Wrap<'_,P>{
fn observe_rule_attempt(&self,r:usize,o:usize,f:u8){self.trace.borrow_mut().push((0,r,o,f));self.inner.observe_rule_attempt(r,o,f)}
fn observe_expression(&self,e:usize,o:usize){self.trace.borrow_mut().push((1,e,o,0));self.inner.observe_expression(e,o)}
fn leading_bytes(&self,e:usize)->Option<$c::lexical::LeadingBytes>{if self.forward{self.inner.leading_bytes(e)}else{None}}
fn atomic_expression(&self,e:usize)->bool{self.forward&&self.inner.atomic_expression(e)}
fn terminal_candidates(&self,e:usize,b:Option<u8>)->Option<&[usize]>{if self.forward{self.inner.terminal_candidates(e,b)}else{None}}
fn terminal_choice(&self,e:usize)->Option<$c::lexical::TerminalChoice<'_>>{if self.forward{self.inner.terminal_choice(e)}else{None}}
flag!(fast_rule_failures,true);flag!(atomic_tail_dispatch,true);flag!(tail_continuations,true);flag!(tail_dispatch,true);flag!(fast_trivia_failures,true);flag!(fast_predicate_failures,true);flag!(fast_ascii_repetitions,false);
fn failure_terminals(&self,r:usize)->&[usize]{if self.forward{self.inner.failure_terminals(r)}else{&[]}}
fn literal_choice_failure(&self,e:usize,s:&str)->Option<usize>{if self.forward{self.inner.literal_choice_failure(e,s)}else{None}}
fn trivia_failure_prefix(&self,r:usize)->Option<$c::lexical::FailurePrefix>{if self.forward{self.inner.trivia_failure_prefix(r)}else{None}}
fn rule_id(&self,n:&str)->Option<usize>{self.inner.rule_id(n)}fn rule(&self,r:usize)->$c::program::RuleSpec<'_>{self.inner.rule(r)}fn instruction(&self,e:usize)->$c::program::Instruction<'_>{self.inner.instruction(e)}
fn source_pratt(&self,r:usize)->Option<$c::program::SourcePratt<'_>>{if self.forward{self.inner.source_pratt(r)}else{None}}
fn scope(&self,id:usize)->$c::program::Scope{let mut s=self.inner.scope(id);if !self.forward{s.whitespace_class=None;s.whitespace_prefix_class=None;}s}
fn whitespace_class(&self)->Option<$c::lexical::ByteClass>{if self.forward{self.inner.whitespace_class()}else{None}}
fn whitespace_prefix_class(&self)->Option<$c::lexical::ByteClass>{if self.forward{self.inner.whitespace_prefix_class()}else{None}}
$($extra)*}}}
observer!(before,);observer!(after,fn observe_profile_rule_result(&self,r:after::program::ProfileRuleOutcome){self.outcomes.borrow_mut().push(r);self.inner.observe_profile_rule_result(r)});
fn run<A:before::program::Program,B:after::program::Program>(lang:&str,old:&A,new:&B,source:&str,count:usize){
for id in 0..count {let spec=new.rule(id);assert_eq!(format!("{:?}",old.rule(id)),format!("{spec:?}"));println!("META\t{lang}\t{id}\t{}\t{}\t{:?}\t{}",spec.name,spec.scope,spec.mode,new.atomic_expression(spec.expression));let mut seen=BTreeSet::new();let mut pending=vec![(spec.expression,false)];while let Some((e,neg))=pending.pop(){if !seen.insert((e,neg)){continue}match new.instruction(e){after::program::Instruction::Sequence{left,right}|after::program::Instruction::Choice{left,right}=>{pending.push((left,neg));pending.push((right,neg));},after::program::Instruction::Group(c)|after::program::Instruction::Push(c)|after::program::Instruction::Repeat{expression:c,..}=>pending.push((c,neg)),after::program::Instruction::Predicate{expression,positive}=>pending.push((expression,neg||!positive)),after::program::Instruction::Call(target)=>println!("EDGE\t{lang}\t{id}\t{target}\t{e}\t{neg}"),_=>{}}}}
let old_tree=before::engine::parse_program(old,"program",source,before::MatchOptions::default()).map(old_shape).map_err(|e|format!("{e:?}"));assert!(old_tree.is_ok());let plain_new=after::engine::parse_program(new,"program",source,after::MatchOptions::default()).map(new_shape).map_err(|e|format!("{e:?}"));assert_eq!(old_tree,plain_new);
for forward in [true,false]{let a=Wrap::new(old,forward);let b=Wrap::new(new,forward);let x=before::engine::parse_program(&a,"program",source,before::MatchOptions::default()).map(old_shape).map_err(|e|format!("{e:?}"));let y=after::engine::parse_program(&b,"program",source,after::MatchOptions::default()).map(new_shape).map_err(|e|format!("{e:?}"));assert_eq!(old_tree,x);assert_eq!(x,y);assert_eq!(*a.trace.borrow(),*b.trace.borrow());println!("PARITY\t{lang}\tcapture\t{forward}\t{}",a.trace.borrow().len());
if forward{for r in b.outcomes.borrow().iter(){let spec=new.rule(r.rule);let body_mode=match spec.mode{after::grammar::RuleMode::Atomic=>1,after::grammar::RuleMode::CompoundAtomic=>2,after::grammar::RuleMode::NonAtomic=>0,_=>r.flags&3};let scope=new.scope(spec.scope);let trivia_pure=scope.whitespace.into_iter().chain(scope.comment).all(|id|new.atomic_expression(new.rule(id).expression));let pure=new.atomic_expression(spec.expression)&&(body_mode!=0||trivia_pure);println!("CALL\t{lang}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",r.rule,spec.name,r.start,r.body_end,r.flags,r.scope,r.parent.map_or(-1,|id|id as isize),r.body_steps,r.after_enter_steps,r.peak_physical_depth,r.peak_virtual_depth,r.matched,r.certificate,pure,r.physical_expression_attempts,r.physical_nested_rule_attempts,r.physical_body_dispatches);}}
a.trace.borrow_mut().clear();b.trace.borrow_mut().clear();let x=before::engine::recognize_program(&a,"program",source,before::MatchOptions::default());let y=after::engine::recognize_program(&b,"program",source,after::MatchOptions::default());assert_eq!(format!("{x:?}"),format!("{y:?}"));assert_eq!(*a.trace.borrow(),*b.trace.borrow());println!("PARITY\t{lang}\trecognition\t{forward}\t{}\t{x:?}",a.trace.borrow().len());}
// Tight resources exercise aborted frames and preserve existing custom calls.
let sample=&source[..source.char_indices().map(|(i,_)|i).filter(|i|*i<=128).last().unwrap_or(0)];let mut checks=0;
for forward in [true,false]{for budget in [0,1,2,7,31,127,511]{for depth in [0,1,2,7,31]{let a=Wrap::new(old,forward);let b=Wrap::new(new,forward);let x=before::engine::parse_program(&a,"program",sample,before::MatchOptions{max_steps:budget,max_rule_depth:depth}).map(old_shape).map_err(|e|format!("{e:?}"));let y=after::engine::parse_program(&b,"program",sample,after::MatchOptions{max_steps:budget,max_rule_depth:depth}).map(new_shape).map_err(|e|format!("{e:?}"));assert_eq!(x,y);assert_eq!(*a.trace.borrow(),*b.trace.borrow());checks+=1;a.trace.borrow_mut().clear();b.trace.borrow_mut().clear();let x=before::engine::recognize_program(&a,"program",sample,before::MatchOptions{max_steps:budget,max_rule_depth:depth});let y=after::engine::recognize_program(&b,"program",sample,after::MatchOptions{max_steps:budget,max_rule_depth:depth});assert_eq!(format!("{x:?}"),format!("{y:?}"));assert_eq!(*a.trace.borrow(),*b.trace.borrow());checks+=1;}}}println!("GUARDS\t{lang}\t{checks}");}
fn main(){std::thread::Builder::new().stack_size(64*1024*1024).spawn(||{let args=env::args().collect::<Vec<_>>();let source=fs::read_to_string(&args[2]).unwrap();match args[1].as_str(){"ruby"=>run("ruby",&before_generated::all::ruby::Parser,&ruby::Parser,&source,ruby::count()),"fortran"=>run("fortran",&before_generated::all::fortran::Parser,&fortran::Parser,&source,fortran::count()),"washm"=>run("washm",&before_generated::all::washm::Parser,&washm::Parser,&source,washm::count()),_=>panic!()}}).unwrap().join().unwrap();}
